if doc.custom_medical_certificate_issued and doc.custom_certificate_valid_from and doc.custom_certificate_valid_to:

    patient = frappe.get_doc("Patient", doc.patient)

    if not patient.custom_employee_id:
        frappe.msgprint("Patient has no Employee ID linked. Leave Application not created.")
    else:
        existing = frappe.db.exists("Leave Application", {
            "employee": patient.custom_employee_id,
            "from_date": doc.custom_certificate_valid_from,
            "to_date": doc.custom_certificate_valid_to,
        })

        if existing:
            frappe.msgprint("Leave Application already exists for this period.")
        else:
            # Check if leave allocation exists
            allocation = frappe.db.exists("Leave Allocation", {
                "employee": patient.custom_employee_id,
                "leave_type": "Sick Leave",
                "from_date": ["<=", doc.custom_certificate_valid_from],
                "to_date": [">=", doc.custom_certificate_valid_to],
                "docstatus": 1
            })

            if not allocation:
                frappe.msgprint(
                    f"No Sick Leave allocation found for {patient.custom_employee_id}. "
                    "Please ask HR to allocate Sick Leave for this employee before issuing a certificate.",
                    alert=True
                )
            else:
                try:
                    leave_app = frappe.new_doc("Leave Application")
                    leave_app.employee = patient.custom_employee_id
                    leave_app.leave_type = "Sick Leave"
                    leave_app.from_date = doc.custom_certificate_valid_from
                    leave_app.to_date = doc.custom_certificate_valid_to
                    leave_app.description = f"Auto-created from Patient Encounter {doc.name} - Medical Certificate Issued"
                    leave_app.status = "Open"
                    leave_app.insert(ignore_permissions=True)
                    frappe.msgprint(
                        f"Leave Application {leave_app.name} created successfully for {patient.custom_employee_id}",
                        alert=True
                    )
                except Exception as e:
                    frappe.log_error(message=str(e), title="Leave Application Auto-Creation Failed")
                    frappe.msgprint(f"Could not create Leave Application: {str(e)}")
